import java.util.*;

class Solution {
    public List<String> ambiguousCoordinates(String s) {
        String digits = s.substring(1, s.length() - 1);
        List<String> result = new ArrayList<>();
        int n = digits.length();

        for (int i = 1; i < n; i++) {
            String left = digits.substring(0, i);
            String right = digits.substring(i);
            List<String> leftNums = makeNumbers(left);
            List<String> rightNums = makeNumbers(right);

            for (String a : leftNums) {
                for (String b : rightNums) {
                    result.add("(" + a + ", " + b + ")");
                }
            }
        }

        return result;
    }

    private List<String> makeNumbers(String t) {
        List<String> res = new ArrayList<>();
        int n = t.length();

        if (n == 1 || t.charAt(0) != '0') {
            res.add(t);
        }

        for (int i = 1; i < n; i++) {
            if (t.charAt(n - 1) == '0') {
                continue;
            }

            String left = t.substring(0, i);
            if (left.length() > 1 && left.charAt(0) == '0') {
                continue;
            }

            res.add(left + "." + t.substring(i));
        }

        return res;
    }
}
