class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] g = new int[m][n];
        for (int i = 0; i < m; i++) {
            g[i] = grid[i].clone();
        }

        int h = hits.length;
        boolean[] wasBrick = new boolean[h];
        for (int i = 0; i < h; i++) {
            int r = hits[i][0];
            int c = hits[i][1];
            if (g[r][c] == 1) {
                wasBrick[i] = true;
                g[r][c] = 0;
            }
        }

        int N = m * n;
        DSU dsu = new DSU(N + 1);
        int top = N;
        dsu.size[top] = 0;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (g[r][c] == 1) {
                    int idx = r * n + c;
                    if (r == 0) {
                        dsu.union(idx, top);
                    }
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] == 1) {
                            dsu.union(idx, nr * n + nc);
                        }
                    }
                }
            }
        }

        int[] ans = new int[h];
        for (int i = h - 1; i >= 0; i--) {
            if (!wasBrick[i]) {
                ans[i] = 0;
                continue;
            }
            int r = hits[i][0];
            int c = hits[i][1];
            int idx = r * n + c;
            int before = dsu.getSize(top);
            g[r][c] = 1;
            if (r == 0) {
                dsu.union(idx, top);
            }
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] == 1) {
                    dsu.union(idx, nr * n + nc);
                }
            }
            int after = dsu.getSize(top);
            ans[i] = Math.max(0, after - before - 1);
        }

        return ans;
    }

    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }

        int getSize(int x) {
            return size[find(x)];
        }
    }
}
