import java.util.ArrayDeque;
import java.util.Deque;

class MKAverage {
    private static final int MAX = 100000;
    private final int m;
    private final int k;
    private final int[] countTree;
    private final long[] sumTree;
    private final Deque<Integer> window;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        this.countTree = new int[MAX + 1];
        this.sumTree = new long[MAX + 1];
        this.window = new ArrayDeque<>();
    }

    public void addElement(int num) {
        window.offer(num);
        updateCount(num, 1);
        updateSum(num, num);

        if (window.size() > m) {
            int old = window.poll();
            updateCount(old, -1);
            updateSum(old, -old);
        }
    }

    public int calculateMKAverage() {
        if (window.size() < m) {
            return -1;
        }

        long middleSum = prefixSum(m - k) - prefixSum(k);
        return (int) (middleSum / (m - 2 * k));
    }

    private void updateCount(int idx, int delta) {
        for (int i = idx; i <= MAX; i += i & -i) {
            countTree[i] += delta;
        }
    }

    private void updateSum(int idx, long delta) {
        for (int i = idx; i <= MAX; i += i & -i) {
            sumTree[i] += delta;
        }
    }

    private int queryCount(int idx) {
        int res = 0;
        for (int i = idx; i > 0; i -= i & -i) {
            res += countTree[i];
        }
        return res;
    }

    private long querySum(int idx) {
        long res = 0;
        for (int i = idx; i > 0; i -= i & -i) {
            res += sumTree[i];
        }
        return res;
    }

    private int findKth(int kth) {
        int idx = 0;
        for (int bit = 1 << 17; bit > 0; bit >>= 1) {
            int next = idx + bit;
            if (next <= MAX && countTree[next] < kth) {
                idx = next;
                kth -= countTree[next];
            }
        }
        return idx + 1;
    }

    private long prefixSum(int cnt) {
        if (cnt <= 0) {
            return 0L;
        }

        int value = findKth(cnt);
        int lessCount = queryCount(value - 1);
        long lessSum = querySum(value - 1);
        int need = cnt - lessCount;

        return lessSum + (long) need * value;
    }
}
```

