class Solution {
    public int maxEqualFreq(int[] nums) {
        int maxVal = 0;
        for (int num : nums) {
            maxVal = Math.max(maxVal, num);
        }

        int[] freq = new int[maxVal + 1];
        int[] countFreq = new int[nums.length + 1];

        int maxFreq = 0;
        int distinct = 0;
        int ans = 0;

        for (int i = 0; i < nums.length; i++) {
            int x = nums[i];

            if (freq[x] > 0) {
                countFreq[freq[x]]--;
            } else {
                distinct++;
            }

            freq[x]++;
            countFreq[freq[x]]++;

            maxFreq = Math.max(maxFreq, freq[x]);

            if (maxFreq == 1
                || (countFreq[maxFreq] == 1 && countFreq[maxFreq - 1] == distinct - 1)
                || (countFreq[1] == 1 && countFreq[maxFreq] == distinct - 1)) {
                ans = i + 1;
            }
        }

        return ans;
    }
}
