class Solution {
    public int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.length;
        int left = 0;
        long sum = 0;
        long max = 0;

        for (int right = 0; right < n; right++) {
            sum += fruits[right][1];

            while (left <= right) {
                int L = fruits[left][0];
                int R = fruits[right][0];
                long steps = (long) R - L + Math.min(
                    Math.abs(startPos - L),
                    Math.abs(startPos - R)
                );

                if (steps <= k) {
                    break;
                }

                sum -= fruits[left][1];
                left++;
            }

            if (left <= right) {
                max = Math.max(max, sum);
            }
        }

        return (int) max;
    }
}
