class Solution {
    public int largestMagicSquare(int[][] grid) {
        int m=grid.length,n=grid[0].length;
        int[][] rowPre=new int[m][n+1];
        int[][] colPre=new int[n][m+1];
        for(int i=0;i<m;i++){
            for(int j=0;j<n;j++){
                rowPre[i][j+1]=rowPre[i][j]+grid[i][j];
            }
        }
        for(int j=0;j<n;j++){
            for(int i=0;i<m;i++){
                colPre[j][i+1]=colPre[j][i]+grid[i][j];
            }
        }
        int maxK=Math.min(m,n);
        for(int k=maxK;k>=1;k--){
            for(int r=0;r+k<=m;r++){
                for(int c=0;c+k<=n;c++){
                    if(isMagic(grid,rowPre,colPre,r,c,k)) return k;
                }
            }
        }
        return 1;
    }
    private boolean isMagic(int[][] grid,int[][] rowPre,int[][] colPre,int r,int c,int k){
        int target=rowPre[r][c+k]-rowPre[r][c];
        for(int i=r;i<r+k;i++){
            int sum=rowPre[i][c+k]-rowPre[i][c];
            if(sum!=target) return false;
        }
        for(int j=c;j<c+k;j++){
            int sum=colPre[j][r+k]-colPre[j][r];
            if(sum!=target) return false;
        }
        int d1=0,d2=0;
        for(int x=0;x<k;x++){
            d1+=grid[r+x][c+x];
            d2+=grid[r+x][c+k-1-x];
        }
        return d1==target && d2==target;
    }
}
