```java
import java.util.Arrays;

class Solution {
    public int maxStudents(char[][] seats) {
        int m = seats.length;
        int n = seats[0].length;
        int N = 1 << n;

        int[] pop = new int[N];
        for (int mask = 1; mask < N; mask++) {
            pop[mask] = pop[mask >> 1] + (mask & 1);
        }

        int[] available = new int[m];
        for (int i = 0; i < m; i++) {
            int rowMask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    rowMask |= 1 << j;
                }
            }
            available[i] = rowMask;
        }

        int[] dp = new int[N];
        Arrays.fill(dp, -1);

        for (int mask = 0; mask < N; mask++) {
            if ((mask & ~available[0]) == 0 && (mask & (mask << 1)) == 0) {
                dp[mask] = pop[mask];
            }
        }

        for (int r = 1; r < m; r++) {
            int[] next = new int[N];
            Arrays.fill(next, -1);

            for (int cur = 0; cur < N; cur++) {
                if ((cur & ~available[r]) != 0) continue;
                if ((cur & (cur << 1)) != 0) continue;

                int best = -1;
                for (int prev = 0; prev < N; prev++) {
                    if (dp[prev] == -1) continue;
                    if (((cur << 1) & prev) == 0 && ((cur >> 1) & prev) == 0) {
                        best = Math.max(best, dp[prev] + pop[cur]);
                    }
                }
                next[cur] = best;
            }

            dp = next;
        }

        int answer = 0;
        for (int value : dp) {
            answer = Math.max(answer, value);
        }
        return answer;
    }
}
```

