class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        int bestNode = 0;
        int minInfected = Integer.MAX_VALUE;

        for (int removed = 0; removed < n; removed++) {
            boolean[] infected = new boolean[n];
            int[] queue = new int[n];
            int head = 0, tail = 0;

            for (int node : initial) {
                if (node != removed) {
                    infected[node] = true;
                    queue[tail++] = node;
                }
            }

            while (head < tail) {
                int u = queue[head++];
                for (int v = 0; v < n; v++) {
                    if (graph[u][v] == 1 && v != removed && !infected[v]) {
                        infected[v] = true;
                        queue[tail++] = v;
                    }
                }
            }

            int count = 0;
            for (boolean b : infected) {
                if (b) count++;
            }

            if (count < minInfected) {
                minInfected = count;
                bestNode = removed;
            }
        }

        return bestNode;
    }
}
