class Solution {
    public int minOperations(String s) {
        int n = s.length();
        int mismatches = 0;
        for (int i = 0; i < n; i++) {
            char expected = (i % 2 == 0) ? '0' : '1';
            if (s.charAt(i) != expected) {
                mismatches++;
            }
        }
        return Math.min(mismatches, n - mismatches);
    }
}
```

```java
class Solution {
    public String maximumBinaryString(String binary) {
        int n = binary.length();
        int zeros = 0;
        int firstZero = -1;

        for (int i = 0; i < n; i++) {
            if (binary.charAt(i) == '0') {
                zeros++;
                if (firstZero == -1) {
                    firstZero = i;
                }
            }
        }

        if (zeros == 0) {
            return binary;
        }

        char[] result = new char[n];
        for (int i = 0; i < n; i++) {
            result[i] = '1';
        }

        result[firstZero + zeros - 1] = '0';

        return new String(result);
    }
}
```

