class Solution {
    private int m, n;
    private int[][] grid;

    public int minDays(int[][] grid) {
        this.grid = grid;
        this.m = grid.length;
        this.n = grid[0].length;

        if (countIslands(-1, -1) != 1) {
            return 0;
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    if (countIslands(i, j) != 1) {
                        return 1;
                    }
                }
            }
        }

        return 2;
    }

    private int countIslands(int skipR, int skipC) {
        boolean[][] visited = new boolean[m][n];
        int count = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !(i == skipR && j == skipC) && !visited[i][j]) {
                    count++;
                    dfs(i, j, skipR, skipC, visited);
                }
            }
        }

        return count;
    }

    private void dfs(int r, int c, int skipR, int skipC, boolean[][] visited) {
        if (r < 0 || r >= m || c < 0 || c >= n) return;
        if (visited[r][c]) return;
        if (grid[r][c] == 0) return;
        if (r == skipR && c == skipC) return;

        visited[r][c] = true;

        dfs(r + 1, c, skipR, skipC, visited);
        dfs(r - 1, c, skipR, skipC, visited);
        dfs(r, c + 1, skipR, skipC, visited);
        dfs(r, c - 1, skipR, skipC, visited);
    }
}
```

