class Solution {
    public int maxSizeSlices(int[] slices) {
        int m = slices.length;
        int n = m / 3;
        int a = maxSum(slices, 0, m - 2, n);
        int b = maxSum(slices, 1, m - 1, n);
        return Math.max(a, b);
    }

    private int maxSum(int[] slices, int start, int end, int k) {
        int len = end - start + 1;
        final int NEG = Integer.MIN_VALUE / 2;
        int[][] dp = new int[len + 1][k + 1];
        for (int i = 0; i <= len; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = NEG;
            }
        }
        dp[0][0] = 0;
        for (int i = 1; i <= len; i++) {
            int val = slices[start + i - 1];
            dp[i][0] = 0;
            for (int j = 1; j <= k; j++) {
                // skip current
                if (dp[i - 1][j] != NEG) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 1][j]);
                }
                // take current
