                    dp[i][j] = Math.max(dp[i][j], val);
                } else if (i >= 2 && dp[i - 2][j - 1] != NEG) {
                    dp[i][j] = Math.max(dp[i][j], dp[i - 2][j - 1] + val);
                }
            }
        }
        return dp[len][k];
    }
}

