class Solution {
    public int minSwaps(String s) {
        int balance = 0;
        int unmatched = 0;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '[') {
                balance++;
            } else {
                if (balance > 0) {
                    balance--;
                } else {
                    unmatched++;
                }
            }
        }

        return (unmatched + 1) / 2;
    }
}
