class Solution {
    private int[] parent;
    private int[] rank;

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    private void union(int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) return;
        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
        } else if (rank[rx] > rank[ry]) {
            parent[ry] = rx;
        } else {
            parent[ry] = rx;
            rank[rx]++;
        }
    }

    public boolean[] friendRequests(int n, int[][] restrictions, int[][] requests) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
        }

        boolean[] result = new boolean[requests.length];

        for (int i = 0; i < requests.length; i++) {
            int u = requests[i][0];
            int v = requests[i][1];
            int ru = find(u);
            int rv = find(v);

            if (ru == rv) {
                result[i] = true;
                continue;
            }

            boolean valid = true;
            for (int[] restriction : restrictions) {
                int rx = find(restriction[0]);
                int ry = find(restriction[1]);

                if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                union(ru, rv);
                result[i] = true;
            } else {
                result[i] = false;
            }
        }

        return result;
    }
}
```

