class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int total = 1 << n;
        int INF = Integer.MAX_VALUE / 2;
        int[] sessions = new int[total];
        int[] used = new int[total];
        Arrays.fill(sessions, INF);
        Arrays.fill(used, INF);
        sessions[0] = 0;
        used[0] = 0;
        for (int mask = 0; mask < total; mask++) {
            if (sessions[mask] == INF) continue;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                int nmask = mask | (1 << i);
                int ns = sessions[mask];
                int nu = used[mask] + tasks[i];
                if (nu > sessionTime) {
                    ns++;
                    nu = tasks[i];
                }
                if (ns < sessions[nmask] || (ns == sessions[nmask] && nu < used[nmask])) {
                    sessions[nmask] = ns;
                    used[nmask] = nu;
                }
            }
        }
        return sessions[total - 1];
