class Solution {
    public int nextBeautifulNumber(int n) {
        java.util.TreeSet<Integer> set = new java.util.TreeSet<>();

        for (int mask = 1; mask < (1 << 7); mask++) {
            int total = 0;
            for (int d = 1; d <= 7; d++) {
                if ((mask & (1 << (d - 1))) != 0) {
                    total += d;
                }
            }
            if (total > 7) continue;

            char[] arr = new char[total];
            int idx = 0;
            for (int d = 1; d <= 7; d++) {
                if ((mask & (1 << (d - 1))) != 0) {
                    for (int k = 0; k < d; k++) {
                        arr[idx++] = (char) ('0' + d);
                    }
                }
            }

            addPermutations(arr, set);
        }

        for (int x : set) {
            if (x > n) {
                return x;
            }
        }

        return -1;
    }

    private void addPermutations(char[] arr, java.util.TreeSet<Integer> set) {
        java.util.Arrays.sort(arr);

        while (true) {
            set.add(Integer.parseInt(new String(arr)));

            int i = arr.length - 2;
            while (i >= 0 && arr[i] >= arr[i + 1]) {
                i--;
            }
            if (i < 0) {
                break;
            }

            int j = arr.length - 1;
            while (arr[j] <= arr[i]) {
                j--;
            }

            char tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;

            for (int l = i + 1, r = arr.length - 1; l < r; l++, r--) {
                tmp = arr[l];
                arr[l] = arr[r];
                arr[r] = tmp;
            }
        }
    }
}
