import java.util.*;

class Solution {
    private int[] nums;
    private TreeSet<Integer> small;
    private TreeSet<Integer> large;
    private Comparator<Integer> cmp;

    public double[] medianSlidingWindow(int[] nums, int k) {
        this.nums = nums;
        cmp = (a, b) -> {
            if (this.nums[a] != this.nums[b]) {
                return Integer.compare(this.nums[a], this.nums[b]);
            }
            return Integer.compare(a, b);
        };
        small = new TreeSet<>(cmp);
        large = new TreeSet<>(cmp);

        int n = nums.length;
        double[] ans = new double[n - k + 1];
        for (int i = 0; i < k; i++) {
            add(i);
        }
        int pos = 0;
        ans[pos++] = getMedian(k);
        for (int i = k; i < n; i++) {
            remove(i - k);
            add(i);
            ans[pos++] = getMedian(k);
        }
        return ans;
    }

    private void add(int idx) {
        if (small.isEmpty() || cmp.compare(idx, small.last()) <= 0) {
            small.add(idx);
        } else {
            large.add(idx);
        }
        balance();
    }

    private void remove(int idx) {
        if (small.contains(idx)) {
            small.remove(idx);
        } else {
            large.remove(idx);
        }
        balance();
    }

    private void balance() {
        while (small.size() > large.size() + 1) {
            int moved = small.pollLast();
            large.add(moved);
        }
        while (small.size() < large.size()) {
            int moved = large.pollFirst();
            small.add(moved);
        }
    }

    private double getMedian(int k) {
        if (k % 2 == 1) {
            return nums[small.last()];
        } else {
            long a = nums[small.last()];
            long b = nums[large.first()];
            return (a + b) / 2.0;
        }
    }
}
