class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int n = nums.length;
        int sum = 0;
        for (int num : nums) sum += num;
        if (sum % k != 0) return false;
        int target = sum / k;
        Arrays.sort(nums);
        for (int i = 0; i < n / 2; i++) {
            int temp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = temp;
        }
        if (nums[0] > target) return false;
        Boolean[] memo = new Boolean[1 << n];
        return dfs(0, nums, target, memo, n);
    }

    private boolean dfs(int mask, int[] nums, int target, Boolean[] memo, int n) {
        if (mask == (1 << n) - 1) return true;
        if (memo[mask] != null) return memo[mask];
        int currentSum = 0;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) currentSum += nums[i];
        }
        currentSum %= target;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0 && currentSum + nums[i] <= target) {
                if (dfs(mask | (1 << i), nums, target, memo, n)) {
                    memo[mask] = true;
                    return true;
                }
            }
        }
        memo[mask] = false;
        return false;
    }
}

