```java
class Solution {
    private int[][][] minDp;
    private int[][][] maxDp;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        minDp = new int[n + 1][n + 1][n + 1];
        maxDp = new int[n + 1][n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= n; k++) {
                    minDp[i][j][k] = -1;
                    maxDp[i][j][k] = -1;
                }
            }
        }
        return dfs(n, firstPlayer, secondPlayer);
    }

    private int[] dfs(int m, int a, int b) {
        if (a + b == m + 1) {
            return new int[]{1, 1};
        }
        if (minDp[m][a][b] != -1) {
            return new int[]{minDp[m][a][b], maxDp[m][a][b]};
        }

        int pairs = m / 2;
        int nextM = (m + 1) / 2;
        int mn = Integer.MAX_VALUE;
        int mx = Integer.MIN_VALUE;
        int masks = 1 << pairs;

        for (int mask = 0; mask < masks; mask++) {
            int winners = 0;
            for (int i = 1; i <= pairs; i++) {
                int opp = m + 1 - i;
                int winner;
                if (i == a || opp == a) {
                    winner = a;
                } else if (i == b || opp == b) {
                    winner = b;
                } else {
                    winner = ((mask >> (i - 1)) & 1) == 0 ? i : opp;
                }
                winners |= 1 << winner;
            }
            if ((m & 1) == 1) {
                winners |= 1 << ((m + 1) / 2);
            }

            int na = Integer.bitCount(winners & ((1 << a) - 1)) + 1;
            int nb = Integer.bitCount(winners & ((1 << b) - 1)) + 1;

            int[] res = dfs(nextM, na, nb);
            mn = Math.min(mn, res[0] + 1);
            mx = Math.max(mx, res[1] + 1);
        }

        minDp[m][a][b] = mn;
        maxDp[m][a][b] = mx;
        return new int[]{mn, mx};
    }
}
```

