```java
import java.util.*;

class Solution {
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        String[] sorted = products.clone();
        Arrays.sort(sorted);

        List<List<String>> result = new ArrayList<>();
        int start = 0;
        StringBuilder prefix = new StringBuilder();

        for (int i = 0; i < searchWord.length(); i++) {
            prefix.append(searchWord.charAt(i));
            String p = prefix.toString();

            while (start < sorted.length && !sorted[start].startsWith(p)) {
                start++;
            }

            List<String> suggestions = new ArrayList<>();
            for (int j = start; j < sorted.length && suggestions.size() < 3; j++) {
                if (sorted[j].startsWith(p)) {
                    suggestions.add(sorted[j]);
                } else {
                    break;
                }
            }

            result.add(suggestions);
        }

        return result;
    }
}
```

