import java.util.*;

class Solution {
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        String[] sorted = products.clone();
        Arrays.sort(sorted);
        List<List<String>> result = new ArrayList<>();
        int start = 0;
        StringBuilder prefix = new StringBuilder();
        for (int k = 0; k < searchWord.length(); k++) {
            prefix.append(searchWord.charAt(k));
            String p = prefix.toString();
            while (start < sorted.length && !sorted[start].startsWith(p)) {
                start++;
            }
            List<String> sugg = new ArrayList<>();
            for (int i = start; i < sorted.length && sugg.size() < 3; i++) {
                if (sorted[i].startsWith(p)) {
                    sugg.add(sorted[i]);
                } else {
                    break;
                }
            }
            result.add(sugg);
        }
        return result;
    }
}

