class Solution {
    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;

        int[] head = new int[n];
        for (int i = 0; i < n; i++) {
            head[i] = -1;
        }

        int m = edges.length;
        int[] to = new int[2 * m];
        int[] next = new int[2 * m];
        int idx = 0;

        for (int[] e : edges) {
            int u = e[0], v = e[1];

            to[idx] = v;
            next[idx] = head[u];
            head[u] = idx++;

            to[idx] = u;
            next[idx] = head[v];
            head[v] = idx++;
        }

        boolean[][] coprime = new boolean[51][51];
        for (int i = 1; i <= 50; i++) {
            for (int j = 1; j <= 50; j++) {
                coprime[i][j] = gcd(i, j) == 1;
            }
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            ans[i] = -1;
        }

        int[] depth = new int[n];
        int[] last = new int[51];
        for (int i = 0; i <= 50; i++) {
            last[i] = -1;
        }

        int[] prev = new int[n];

        int capacity = 2 * n + 5;
        int[] stackNode = new int[capacity];
        int[] stackParent = new int[capacity];
        int[] stackState = new int[capacity];

        int top = 0;
        stackNode[top] = 0;
        stackParent[top] = -1;
        stackState[top] = 0;
        top++;

        while (top > 0) {
            top--;
            int node = stackNode[top];
            int parent = stackParent[top];
            int state = stackState[top];

            if (state == 0) {
                int val = nums[node];

                int best = -1;
                int bestDepth = -1;

                for (int g = 1; g <= 50; g++) {
                    if (last[g] != -1 && coprime[val][g]) {
                        int cand = last[g];
                        if (depth[cand] > bestDepth) {
                            bestDepth = depth[cand];
                            best = cand;
                        }
                    }
                }

                ans[node] = best;

                prev[node] = last[val];
                last[val] = node;

                stackNode[top] = node;
                stackParent[top] = parent;
                stackState[top] = 1;
                top++;

                for (int e = head[node]; e != -1; e = next[e]) {
                    int nei = to[e];
                    if (nei == parent) {
                        continue;
                    }

                    depth[nei] = depth[node] + 1;

                    stackNode[top] = nei;
                    stackParent[top] = node;
                    stackState[top] = 0;
                    top++;
                }
            } else {
                int val = nums[node];
                last[val] = prev[node];
            }
        }

        return ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}
