        int[] depth = new int[n];
        int[] last = new int[51];
        Arrays.fill(last, -1);
        int[] prev = new int[n];

        int capacity = 2 * n + 5;
        int[] stackNode = new int[capacity];
        int[] stackParent = new int[capacity];
        int[] stackState = new int[capacity];
        int top = 0;
        stackNode[top] = 0;
        stackParent[top] = -1;
        stackState[top] = 0;
        top++;

        while (top > 0) {
