class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] result = new int[total][2];
        int count = 0;

        int r = rStart;
        int c = cStart;

        if (r >= 0 && r < rows && c >= 0 && c < cols) {
            result[count][0] = r;
            result[count][1] = c;
            count++;
        }

        int[] dr = {0, 1, 0, -1};
        int[] dc = {1, 0, -1, 0};

        int dir = 0;
        int step = 1;

        while (count < total) {
            for (int twice = 0; twice < 2 && count < total; twice++) {
                for (int i = 0; i < step && count < total; i++) {
                    r += dr[dir];
                    c += dc[dir];

                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        result[count][0] = r;
                        result[count][1] = c;
                        count++;
                    }
                }
                dir = (dir + 1) % 4;
            }
            step++;
        }

        return result;
    }
}
