        if (col == maxLen) return carry == 0;
        return processAddends(col, carry, 0, carry);
    }

    private boolean processAddends(int col, int carry, int wordIndex, int sum) {
        if (wordIndex == n) {
            int digit = sum % 10;
            int newCarry = sum / 10;
            char r = (col < result.length()) ? result.charAt(result.length() - 1 - col) : 0;
            if (r == 0) {
