                    map[ri] = -1;
                    return ok;
                } else {
                    if (map[ri] != digit) return false;
                    return dfs(col + 1, newCarry);
                }
            }
        }
        String w = words[wordIndex];
        if (col >= w.length()) {
            return processAddends(col, carry, wordIndex + 1, sum);
        }
        char c = w.charAt(w.length() - 1 - col);
        int ci = c - 'A';
        if (map[ci] != -1) {
