class Solution {
    private String[] words;
    private String result;
    private int[] map;
    private boolean[] used;
    private boolean[] leading;
    private int maxLen;
    private int n;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        this.n = words.length;
        this.map = new int[26];
        for (int i = 0; i < 26; i++) map[i] = -1;
        this.used = new boolean[10];
        this.leading = new boolean[26];
        this.maxLen = result.length();
        for (String w : words) {
            if (w.length() > maxLen) maxLen = w.length();
            leading[w.charAt(0) - 'A'] = true;
        }
        leading[result.charAt(0) - 'A'] = true;
        return dfs(0, 0);
    }

    private boolean dfs(int col, int carry) {
        if (col == maxLen) return carry == 0;
        return processColumn(col, 0, carry);
    }

    private boolean processColumn(int col, int wordIndex, int sum) {
        if (wordIndex == n) {
            int digit = sum % 10;
            int newCarry = sum / 10;
            if (col >= result.length()) {
                if (digit != 0) return false;
                return dfs(col + 1, newCarry);
            }
            char r = result.charAt(result.length() - 1 - col);
            int ri = r - 'A';
            if (map[ri] == -1) {
                if (used[digit] || (digit == 0 && leading[ri])) return false;
                map[ri] = digit;
                used[digit] = true;
                if (dfs(col + 1, newCarry)) return true;
                used[digit] = false;
                map[ri] = -1;
                return false;
            } else {
                if (map[ri] != digit) return false;
                return dfs(col + 1, newCarry);
            }
        }

        String w = words[wordIndex];
        if (col >= w.length()) {
            return processColumn(col, wordIndex + 1, sum);
        }
        char c = w.charAt(w.length() - 1 - col);
        int ci = c - 'A';
        if (map[ci] != -1) {
            return processColumn(col, wordIndex + 1, sum + map[ci]);
        }
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (d == 0 && leading[ci]) continue;
            map[ci] = d;
            used[d] = true;
            if (processColumn(col, wordIndex + 1, sum + d)) return true;
            used[d] = false;
            map[ci] = -1;
        }
        return false;
    }
}

