                    char old = chars[j];
                    for (char c='a'; c<='z'; c++) {
                        if (c==old) continue;
                        chars[j]=c;
                        String next = new String(chars);
                        if (next.equals(endWord)) return level+1;
                        if (dict.contains(next)) {
                            dict.remove(next);
                            q.offer(next);
                        }
                    }
                    chars[j]=old;
                }
            }
            level++;
        }
        return 0;
    }
}
